import re

PAIR = re.compile(r"(\w+)=(\"[^\"]*\"|\S+)")

def parse_logfmt(line):
    out = {}
    for key, raw in PAIR.findall(line):
        if raw.startswith("\"") and raw.endswith("\""):
            out[key] = raw[1:-1]
            continue
        try:
            out[key] = int(raw)
        except ValueError:
            try:
                out[key] = float(raw)
            except ValueError:
                out[key] = raw
    return out
